-- Generated by wiring-auth-go-v1.0 — refresh-token rotation schema.
-- Vansham V2 §3.4 fix. Two tables:
--
--   refresh_token_families    one row per login session
--   refresh_tokens             one row per issued token (chained by family_id)
--
-- The family-level revoked_at column carries the reuse-detection signal —
-- any token whose family is revoked = denied. Rotation marks rotated_at
-- on the old token and inserts a new row in the same family atomically.

CREATE EXTENSION IF NOT EXISTS "pgcrypto";

CREATE TABLE IF NOT EXISTS refresh_token_families (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     UUID NOT NULL,
  started_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  revoked_at  TIMESTAMPTZ NULL
);

CREATE INDEX IF NOT EXISTS idx_refresh_token_families_user
  ON refresh_token_families (user_id) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS refresh_tokens (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  family_id   UUID NOT NULL REFERENCES refresh_token_families(id) ON DELETE CASCADE,
  user_id     UUID NOT NULL,
  -- SHA-256 of the client-side raw token. Raw is never persisted.
  token_hash  BYTEA NOT NULL,
  issued_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at  TIMESTAMPTZ NOT NULL,
  -- Non-null = this token has been rotated. Presenting it again
  -- triggers family revocation (reuse detection).
  rotated_at  TIMESTAMPTZ NULL,
  UNIQUE (token_hash)
);

CREATE INDEX IF NOT EXISTS idx_refresh_tokens_family
  ON refresh_tokens (family_id);

CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user_active
  ON refresh_tokens (user_id) WHERE rotated_at IS NULL;
